            .into_iter()
            .find(|family| family.feature == "qwen4")
            .expect("the qwen4 family is always listed");
        assert_eq!(family.model_types, [MODEL_TYPE].as_slice());
        assert_eq!(family.text_model_types, [TEXT_MODEL_TYPE].as_slice());
    }
}

