//! The step-batched wire contract between a model scheduler and a frontend.
//!
//! One scheduler step produces one [`StepOutputs`] message. Per request the
//! step carries at most one [`RequestUpdate`] — a flat record rather than an
//! event sequence, so the intra-step ordering rules of the old `TokenEvent`
//! protocol (`Scheduled` before tokens before a single terminal) are structure,
//! not convention: a `RequestUpdate` cannot express a token after its terminal.
//! Cross-step ordering is enforced on the producer side by the
//! [`super::RequestLedger`]: a request's account closes at its terminal, and
//! writes against a closed account panic.

use std::fmt;
use std::time::Instant;

use super::event::FinishReason;
use super::event::TokenLogprob;
use super::stop::StopCause;
use super::stop::StopPolicy;

/// In-process routing id for one generate request, minted by
/// [`super::SchedulerHandle::submit`] from a per-scheduler counter. `Copy` and
/// integer-keyed on purpose: the external protocol's string request id stays in
/// the protocol stack, which maps it to this id at its own boundary.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct RequestId(u64);

impl RequestId {
    /// Minting ids is [`super::SchedulerHandle::submit`]'s job in production
    /// (a per-scheduler counter). Public so scheduler unit tests and tools
    /// can fabricate requests.

//! [`RequestLedger`] — the account book of live requests, and the per-step
//! statement it ships on the step stream.
//!
//! One account per unanswered request. The driver opens it at
//! [`RequestLedger::register`]; exactly one terminal transition closes it
//! ([`RequestLedger::finish`], [`RequestLedger::fail`],
//! [`RequestLedger::reject`], [`RequestLedger::retire`], or
//! [`RequestLedger::defer_finish`]); accounts still open when the ledger
//! drops are written off as `Failed` terminals (engine teardown). Because
//! every open is a submit and every close is a terminal, "terminal exactly
//! once" and "nothing after the terminal" are enforced here: touching a
//! closed or unknown account panics at the offending scheduler call site.
//!
//! Token counts on terminals derive from the ledger's own tally
//! ([`RequestLedger::push_tokens`]), never from model-side arithmetic.
//!
//! Scheduler-facing methods are `pub`. Opening accounts and shipping the
//! statement ([`RequestLedger::register`], [`RequestLedger::commit_step`],
//! [`RequestLedger::fail_all`]) are `pub(crate)`: the driver owns the
//! cadence, and model crates cannot reach them.

use std::collections::HashMap;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::Ordering;
use std::time::Instant;

use super::event::FinishReason;
use super::event::TokenLogprob;
use super::request_lifecycle::DeferredFinish;

//! Submission envelope and late-delivery handles for one request's lifetime.
//!
//! The scheduler side of the contract deals in plain [`RequestId`]s against
//! the [`super::RequestLedger`] — no per-request typestate handles cross the
//! `Scheduler` trait. What lives here are the pieces that carry a request
//! *outside* the ledger's reach and therefore need their own answer-on-drop
//! guarantee:
//!
//! - [`RequestEnvelope`] — the channel envelope between
//!   [`super::SchedulerHandle::submit`] and the driver's
//!   [`super::RequestLedger::register`]. It covers the window where the
//!   request exists but no ledger account does yet: sitting in the submit
//!   channel, or sent to a scheduler thread that already exited.
//! - [`DeferredFinish`] — a finish extracted from the ledger for delivery
//!   from another thread at a later time (P/D prefill roles withhold
//!   `Finished` until the step's KV saves are peer-visible).
//! - [`RequestControl`] — the frontend's per-request abort flag.
//!
//! The first two hold `Option<inner>` for one reason only: Rust's `Drop`
//! cannot move fields out, so a consuming transition `take`s the inner and
//! the drop bomb fires on `Some`. An unanswered request must surface as a
//! `Failed` terminal, never a client hang.

use std::sync::Arc;
use std::sync::atomic::AtomicBool;

//! What the scheduler republishes about itself: [`SchedulerMetrics`], the
//! per-iteration snapshot of occupancy gauges plus whatever richer counters a
//! model line serves (today: cumulative speculative-decode acceptance, when a
//! draft model is loaded, and cumulative prefix-cache lookups, when the engine
//! has a prefix cache).

use std::error::Error;
use std::fmt;

/// The metrics snapshot a scheduler republishes after every step.
///
/// `kv_used_blocks` is the load signal an out-of-band consumer (e.g. a Dynamo
/// KV router) scores against; `kv_total_blocks` is the engine's whole-pool
/// capacity (the same number advertised as the servable ceiling), so the
/// consumer can derive fractional usage without a second query. Readers only
/// ever see the latest snapshot — stepped engines publish into a shared cell
/// ([`super::MetricsPublisher`]), legacy engines over a `watch` channel — so
/// counters carried here must be cumulative totals, not per-step deltas (see
/// [`SpecDecodeCounters`]).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SchedulerMetrics {
    pub kv_used_blocks: u64,
    pub kv_total_blocks: u64,
    /// Requests currently occupying a decode/prefill slot.
    pub num_running_reqs: u64,

//! The model-side runtime trait and the polling loop that drives it.
//!
//! The loop lives here — once, for every model line — so its conventions
//! (drain order, one metrics publish and one commit per iteration, shutdown
//! and fatal handling) are code, not per-crate discipline. A model line's
//! runtime obligation is exactly the three [`Scheduler`] methods. Anything
//! beyond them (e.g. LoRA control) is not the contract's business: a
//! scheduler that serves an extra capability captures its own channel before
//! spawn and drains it inside `step`.

use super::ledger::RequestLedger;
use super::metrics::SchedulerMetrics;
use super::step::QueuedRequest;
use super::wiring::LiveScheduler;
use super::wiring::SchedulerBackend;
use super::wiring::scheduler_pair;

/// One scheduler's runtime behavior. Runs on a dedicated OS thread spawned
/// by [`spawn_scheduler`]; `Send` suffices.
pub trait Scheduler: Send {
    /// Take ownership of one submitted request. Ownership transfer only —
    /// every verdict (admit/reject/retire) is written to the ledger from
    /// [`Self::step`], the single emission site. Nothing is lost by
    /// deferring: the driver commits once per iteration, so a verdict
    /// recorded in `step` lands in the same commit a submit-time verdict
    /// would have.
    fn submit(&mut self, request: QueuedRequest);

    /// Advance one step: admission, GPU work, and per-request ledger writes.
    /// The driver loops over this without pause — an idle scheduler returns
    /// quickly and gets polled again, so in-flight completions from the
    /// scheduler's own worker threads are picked up within a step. Recoverable
    /// execution failures are the scheduler's to absorb (fail the touched
    /// requests, keep serving); `Err` means the engine is beyond use. The
    /// driver then writes off every open account with the error and winds
    /// down.
    fn step(&mut self, ledger: &mut RequestLedger) -> anyhow::Result<()>;

    /// Metrics snapshot; the driver publishes it once per iteration.
